        if (remainingDivisors % (exponent + 1) == 0) {
            dfs(index + 1, exponent,
                remainingDivisors / (exponent + 1), value * power);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    cin >> n;

    dfs(0, 62, n, 1);

